#!/usr/bin/env python3
"""Author paragraph overviews; these drafts are not completeness/review evidence."""
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'stereo-course/merzlyak-10-base/lessons'
BOOK = 'merzlyak-2022-10-base'
CHAPTERS = ['Глава 1. Введение в стереометрию', 'Глава 2. Параллельность в пространстве',
            'Глава 3. Перпендикулярность в пространстве', 'Глава 4. Многогранники']
TITLES = [
 'Основные понятия и аксиомы стереометрии', 'Следствия из аксиом стереометрии',
 'Пространственные фигуры и первые сечения', 'Взаимное расположение прямых',
 'Параллельность прямой и плоскости', 'Параллельность плоскостей',
 'Преобразования и параллельное проектирование', 'Угол между прямыми',
 'Перпендикулярность прямой и плоскости', 'Перпендикуляр и наклонная',
 'Теорема о трёх перпендикулярах', 'Угол между прямой и плоскостью',
 'Двугранный угол и угол между плоскостями', 'Перпендикулярные плоскости',
 'Площадь ортогональной проекции', 'Призма', 'Параллелепипед', 'Пирамида',
 'Усечённая пирамида']
RANGES = [(6,10),(13,14),(16,21),(32,37),(40,45),(50,55),(59,68),(82,85),
          (87,94),(98,102),(107,108),(112,114),(118,122),(127,131),(135,137),
          (147,152),(157,160),(162,166),(171,173)]

def view(label, segments=None, polygon=None, points=None):
    d={'label':label}
    if segments: d['segments']=segments
    if polygon: d['polygon']=polygon
    if points: d['points']=points
    return d

def model(points, edges, views, faces=None, labels=None, planar=False):
    d={'points':points,'edges':edges,'views':{'neutral':view('Исходная модель: сопоставь названия точек с пояснением.'),**views}}
    if faces: d['faces']=faces
    d['labelNames']=labels if labels is not None else list(points)
    if planar: d['planar']=True
    return d

def step(title,prompt,explanation,reason,view_name='neutral',kind='theorem'):
    return {'title':title,'prompt':prompt,'explanation':explanation,
            'justifications':[{'kind':kind,'text':reason}],'view':view_name}

def write(n, goal, scene, steps, hint, caption):
    start,end=RANGES[n-1]
    chapter=CHAPTERS[0 if n<=3 else 1 if n<=7 else 2 if n<=15 else 3]
    for i,s in enumerate(steps,1): s['id']=f'step-{i}'
    lesson={'schemaVersion':1,'revision':1,'id':f'merz-theory-{n:02}',
       'kind':'theory','title':f'§ {n}. {TITLES[n-1]} · обзор','status':'draft',
       'source':{'bookId':BOOK,'collection':'theory','point':str(n),'subpart':'обзор',
                 'chapter':chapter,'printedPages':list(range(start,end+1)),
                 'pdfPages':list(range(start+1,end+2))},
       'statement':{'text':f'Обзор основных идей § {n}. '+goal,
                    'goal':goal},
       'visualization':{'type':'scene3d','caption':caption+' Модель иллюстрирует указанные отношения; измерять длины по экрану не нужно. Плоскости и прямые продолжаются за пределы показанных фрагментов.', 'model':scene},
       'help':[{'id':'help-1','question':'С чего начать, если обозначения путаются?',
                'text':hint,'children':[]}],
       'steps':steps,
       'answer':{'mode':'manual','prompt':'Запиши своими словами главное правило и условия, при которых его можно применять. Запись сохраняется для обсуждения с преподавателем; доказательство автоматически не оценивается.'},
       'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/f'theory-{n:02}.json').write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n')

# 1. Two planes meet along AB; C is on the horizontal plane, D outside it.
p={'A':[-2,0,0],'B':[2,0,0],'C':[0,2,0],'D':[0,0,2]}
m=model(p,[['A','B'],['A','C'],['B','C'],['A','D'],['B','D']],
 {'plane':view('Фрагмент плоскости ABC',polygon=['A','B','C']),
  'line':view('Две точки A и B и вся прямая AB в плоскости ABC',segments=[['A','B']],points=['A','B']),
  'other':view('Плоскость ABD и общая прямая AB',polygon=['A','B','D'],segments=[['A','B']])},
 [['A','B','C'],['A','B','D']])
write(1,'Различать точку, прямую, плоскость и применять четыре аксиомы именно в нумерации Мерзляка.',m,[
 step('Три основных понятия','Найди точку A, прямую AB и плоскость ABC.','Точка, прямая и плоскость принимаются как основные понятия. Треугольная закраска показывает лишь часть бесконечной плоскости; отрезок AB показывает часть бесконечной прямой.','§ 1: основные понятия.','plane','definition'),
 step('Читаем символы','Почему для точки и для прямой нужны разные записи?','A∈ABC означает: точка A принадлежит плоскости ABC. AB⊂ABC означает: вся прямая AB лежит в этой плоскости. D∉ABC: точка D вне неё. Равенство a∩α={M} означает единственную общую точку прямой и плоскости.','§ 1: принадлежность и пересечение.','line','definition'),
 step('Аксиома A1','Можно ли внутри пространственной грани использовать теорему Пифагора?','В каждой плоскости пространства действуют аксиомы планиметрии и их следствия. Поэтому, выделив нужную плоскую фигуру, можно пользоваться знакомыми теоремами о треугольниках и четырёхугольниках.','Мерзляк, аксиома A1.','plane'),
 step('Аксиома A2','Что важно проверить у трёх точек A, B, C?','Если три точки не лежат на одной прямой, через них проходит ровно одна плоскость. На модели C не принадлежит AB. Для трёх точек одной прямой условие A2 не выполнено: такая тройка не задаёт плоскость однозначно.','Мерзляк, аксиома A2.','plane'),
 step('Аксиома A3','Почему достаточно проверить две точки прямой?','Если две различные точки прямой лежат в плоскости, то в ней лежит вся прямая. Поэтому A,B∈ABC дают AB⊂ABC. Прямая, не лежащая в плоскости, не может иметь с ней две общие точки.','Мерзляк, аксиома A3.','line'),
 step('Аксиома A4','Где находятся все общие точки плоскостей ABC и ABD?','Две различные плоскости с общей точкой пересекаются по прямой. Здесь у них общие точки A и B, поэтому линия пересечения — AB. Любая другая общая точка этих плоскостей также лежит на AB.','Мерзляк, аксиома A4; через две точки проходит единственная прямая.','other')],
 'Сначала назови объект словами: точка A, прямая AB, плоскость ABC. Затем прочитай символ ∈ как «точка принадлежит», а ⊂ как «вся прямая лежит».',
 'Две различные плоскости ABC и ABD имеют общую прямую AB.')

# 2. A line BC plus external A and the two intersecting lines AB, BC.
p={'B':[-2,0,0],'C':[2,0,0],'A':[0,2,0]}
m=model(p,[['A','B'],['B','C'],['A','C']],
 {'given':view('Прямая BC и внешняя точка A',segments=[['B','C']],points=['A']),
  'plane':view('Единственная плоскость ABC',polygon=['A','B','C']),
  'cross':view('Пересекающиеся прямые AB и BC',segments=[['A','B'],['B','C']],points=['B'])},[['A','B','C']],planar=True)
write(2,'Понимать, почему прямая с внешней точкой или две пересекающиеся прямые задают единственную плоскость.',m,[
 step('Плоскость через прямую и точку','Почему A нельзя выбирать на прямой BC?','Условие теоремы 2.1: точка A не лежит на данной прямой. Если A лежит на ней, остаётся одна прямая, через которую можно провести разные плоскости.','Теорема 2.1, условие.','given'),
 step('Доказываем существование','Выбери две различные точки B и C на прямой.','Точки A,B,C не коллинеарны. По A2 существует плоскость ABC. По A3 вместе с B и C она содержит всю прямую BC. Значит, плоскость проходит и через прямую, и через A.','Аксиомы A2 и A3.','plane'),
 step('Доказываем единственность','Может ли ещё одна плоскость содержать A и BC?','Любая такая плоскость содержит A,B,C. Но через эти три неколлинеарные точки по A2 проходит лишь одна плоскость. Поэтому новая плоскость совпала бы с ABC.','Аксиома A2: единственность.','plane'),
 step('Две пересекающиеся прямые','В какой точке пересекаются AB и BC?','Пусть две различные прямые встречаются в B. Возьми на одной из них A≠B. Эта точка не лежит на другой прямой BC. Теорема 2.1 задаёт плоскость через A и BC; по A3 она содержит также AB.','Теорема 2.2; теорема 2.1 и A3.','cross'),
 step('Три способа задания плоскости','Для каждого способа назови обязательное условие.','Плоскость однозначно задают: три неколлинеарные точки; прямая и точка вне неё; две пересекающиеся прямые. Слова «вне», «не на одной прямой», «пересекающиеся» исключают случаи, когда единственности нет.','Аксиома A2; теоремы 2.1 и 2.2.','plane')],
 'Доказательство существования отвечает «как построить хотя бы одну плоскость?». Доказательство единственности отвечает «почему любая другая обязана совпасть с ней?».',
 'Плоская схема показывает оба способа задания одной и той же плоскости.')

# 3. Mid-edge triangular section of a tetrahedron.
p={'A':[-2,-1,0],'B':[2,-1,0],'C':[0,2,0],'S':[0,0,3],
   'M':[-1,-.5,1.5],'N':[1,-.5,1.5],'P':[0,1,1.5]}
e=[['A','B'],['B','C'],['C','A'],['S','A'],['S','B'],['S','C']]
m=model(p,e,{'base':view('Основание ABC',polygon=['A','B','C']),
 'side':view('Боковая грань SAB',polygon=['S','A','B']),
 'section':view('Сечение MNP: каждая сторона лежит в одной грани',polygon=['M','N','P'],segments=[['M','N'],['N','P'],['P','M']])},
 [['A','B','C'],['S','A','B'],['S','B','C'],['S','C','A']])
write(3,'Узнавать элементы многогранника и понимать, как строится сечение по граням.',m,[
 step('Пространственная фигура','Почему SABC нельзя целиком разместить в плоскости ABC?','Вершина S находится вне плоскости ABC. Поэтому не все точки фигуры лежат в одной плоскости. Это пространственная фигура. Шар, цилиндр и конус тоже пространственные фигуры, но их поверхности не состоят только из многоугольников.','§ 3: пространственные фигуры и первые представления о многогранниках.','neutral','definition'),
 step('Грани, рёбра, вершины','Назови грань, ребро и вершину показанной фигуры.','Грани многогранника — многоугольники его поверхности; их стороны — рёбра, а вершины — вершины многогранника. Например, SAB — грань, SA — ребро, S — вершина.','§ 3: элементы многогранника.','side','definition'),
 step('Пирамида и тетраэдр','Что общего у трёх боковых граней SABC?','Боковые грани SAB,SBC,SCA — треугольники с общей вершиной S; ABC — основание. Треугольная пирамида называется тетраэдром. У неё четыре грани, четыре вершины и шесть рёбер.','§ 3: начальные понятия о пирамиде.','base','definition'),
 step('Чем отличается призма','Сколько оснований имеет призма?','У призмы два равных многоугольных основания в параллельных плоскостях; соответствующие боковые грани — параллелограммы. В прямоугольном параллелепипеде все грани — прямоугольники, в кубе — равные квадраты. Текущая модель показывает тетраэдр, а не призму.','§ 3: начальные понятия о призме, параллелепипеде и кубе.','neutral','definition'),
 step('Что называют сечением','Какая фигура остаётся общей у тела и секущей плоскости?','Если общие точки многогранника и плоскости образуют многоугольник, он называется сечением. На модели секущая плоскость проходит через M,N,P, и сечение — треугольник MNP.','§ 3: определение сечения.','section','definition'),
 step('Почему соединяем именно эти точки','В какой грани одновременно находятся M и N?','M,N лежат в грани SAB, поэтому отрезок MN — часть линии пересечения её плоскости с секущей плоскостью. Аналогично NP лежит в SBC, а PM — в SCA. Соединять точки разных граней без обоснования нельзя.','Аксиомы A3,A4; построение сечения по двум общим точкам.','section')],
 'Сначала выдели одну грань. Найди на ней две точки секущей плоскости. Только затем проводи на этой грани сторону сечения.',
 'Тетраэдр SABC и его сечение через середины M,N,P боковых рёбер; этот пример иллюстрирует общий принцип построения.')

def box(a=4,b=3,c=3):
    p={'A':[0,0,0],'B':[a,0,0],'C':[a,b,0],'D':[0,b,0],
       'A1':[0,0,c],'B1':[a,0,c],'C1':[a,b,c],'D1':[0,b,c]}
    e=[['A','B'],['B','C'],['C','D'],['D','A'],['A1','B1'],['B1','C1'],['C1','D1'],['D1','A1'],['A','A1'],['B','B1'],['C','C1'],['D','D1']]
    f=[['A','B','C','D'],['A1','B1','C1','D1'],['A','B','B1','A1'],['B','C','C1','B1'],['C','D','D1','C1'],['D','A','A1','D1']]
    return p,e,f

p,e,f=box(3,3,3)
m=model(p,e,{'parallel':view('AB и DC: одна плоскость, общих точек нет',segments=[['A','B'],['D','C']],polygon=['A','B','C','D']),
 'cross':view('AB и AD пересекаются в A',segments=[['A','B'],['A','D']],points=['A']),
 'skew':view('AB и CC₁: нет общей плоскости',segments=[['A','B'],['C','C1']],points=['C'])},f)
write(4,'Различать пересекающиеся, параллельные и скрещивающиеся прямые и обосновывать выбор.',m,[
 step('Общая точка','Найди общую точку AB и AD.','Две различные прямые пересекаются, если у них ровно одна общая точка. Через них проходит единственная плоскость. На модели AB∩AD={A}.','§ 4 и теорема 2.2.','cross','definition'),
 step('Параллельность','Почему недостаточно сказать только «не пересекаются»?','В пространстве параллельными называют прямые, которые лежат в одной плоскости и не пересекаются. AB и DC лежат в ABCD и параллельны как противоположные стороны квадрата.','§ 4: определение параллельных прямых.','parallel','definition'),
 step('Скрещивание','В какой точке CC₁ пересекает плоскость ABCD?','CC₁ пересекает плоскость ABCD в C, а C не лежит на AB. По признаку скрещивающихся прямых AB и CC₁ не лежат в одной плоскости. Поэтому они скрещиваются.','Теорема 4.3: одна прямая в плоскости, другая пересекает её вне первой прямой.','skew'),
 step('Почему признак работает','Предположи, что AB и CC₁ всё-таки лежат в одной плоскости β.','Тогда β содержит AB и C. Прямая AB и внешняя точка C задают единственную плоскость ABC. Значит, β=ABC и CC₁ должна лежать в ABC. Это противоречит тому, что CC₁ пересекает ABC только в C.','Теорема 2.1; доказательство теоремы 4.3 от противного.','skew'),
 step('Плоскость через две параллельные прямые','Есть ли выбор у плоскости, содержащей AB и DC?','Существование общей плоскости входит в определение параллельности. Единственность следует из теоремы о прямой и внешней точке: достаточно взять AB и любую точку DC.','Теорема 4.1.','parallel'),
 step('Параллельная через внешнюю точку','Сколько прямых через D параллельно AB?','Ровно одна — DC. Сначала прямая AB и точка D задают плоскость; в ней действует аксиома параллельности планиметрии. Любая пространственная прямая через D, параллельная AB, должна оказаться в этой же плоскости.','Теорема 4.2.','parallel')],
 'Проверяй два разных вопроса: есть ли общая точка и есть ли общая плоскость. На плоской картинке скрещивающиеся прямые могут выглядеть пересекающимися.',
 'Куб даёт по одному конкретному примеру всех трёх взаимных положений прямых.')

p={'A':[-2,-1,0],'B':[2,-1,0],'C':[2,2,0],'D':[-2,2,0],'E':[-2,-1,2],'F':[2,-1,2]}
m=model(p,[['A','B'],['B','C'],['C','D'],['D','A'],['E','F']],
 {'base':view('Плоскость α=ABC',polygon=['A','B','C','D']),
  'criterion':view('EF∥AB, AB лежит в α, EF не лежит в α',segments=[['E','F'],['A','B']]),
  'section':view('Плоскость ABEF пересекает α по AB',polygon=['A','B','F','E'],segments=[['A','B'],['E','F']])},[['A','B','C','D']])
write(5,'Доказывать параллельность прямой и плоскости и пользоваться направлением линии пересечения.',m,[
 step('Три положения','Сколько общих точек могут иметь прямая и плоскость?','Прямая либо лежит в плоскости, либо пересекает её в одной точке, либо не имеет с ней общих точек. Только последний случай называется параллельностью прямой и плоскости.','§ 5: определение.','base','definition'),
 step('Признак параллельности','Какие три факта нужно проверить для EF?','На модели EF∥AB, прямая AB лежит в α, а EF в α не лежит. Тогда EF∥α. Последнее условие обязательно: прямая внутри α не считается параллельной α.','Теорема 5.1.','criterion'),
 step('Доказательство признака','Что получилось бы, если EF встретила α в M?','Если M лежит на AB, прямые EF и AB пересеклись бы. Если M вне AB, по признаку скрещивания EF и AB были бы скрещивающимися. Оба вывода противоречат EF∥AB. Значит, общей точки с α нет.','Теорема 4.3; доказательство теоремы 5.1.','criterion'),
 step('След секущей плоскости','Плоскость ABEF проходит через EF. Почему её след на α параллелен EF?','EF и линия пересечения AB лежат в одной плоскости. Их общая точка была бы общей точкой EF и α, что невозможно. Следовательно, EF∥AB. Так определяется направление сечения на другой грани.','Теорема 5.2.','section'),
 step('Параллельная внутри плоскости','Всегда ли можно найти в α прямую, параллельную EF?','Да. Проведи вспомогательную плоскость через EF и любую точку α. Её линия пересечения с α параллельна EF по предыдущему свойству.','Следствие из теоремы 5.2.','section'),
 step('Ещё два правила о направлениях','Что связывает три параллельных направления?','Если через две параллельные прямые проведены плоскости и их общая прямая отличается от обеих исходных, общая прямая параллельна им. Кроме того, две различные прямые, параллельные третьей, параллельны между собой. Эти правила позволяют переносить известное направление между гранями.','Теоремы 5.3 и 5.4.','criterion')],
 'Для признака выпиши отдельно: a∥b; b⊂α; a⊄α. Только после этого пиши a∥α.',
 'Прямая EF над плоскостью ABCD параллельна AB; плоскость ABEF показывает след секущей плоскости.')

p={'A':[-2,-1,0],'B':[2,-1,0],'C':[0,2,0],'A1':[-2,-1,2],'B1':[2,-1,2],'C1':[0,2,2]}
e=[['A','B'],['B','C'],['C','A'],['A1','B1'],['B1','C1'],['C1','A1'],['A','A1'],['B','B1']]
m=model(p,e,{'lower':view('Плоскость ABC',polygon=['A','B','C']),
 'upper':view('Плоскость A₁B₁C₁',polygon=['A1','B1','C1']),
 'pairs':view('Две пары направлений: AB∥A₁B₁ и AC∥A₁C₁',segments=[['A','B'],['A','C'],['A1','B1'],['A1','C1']]),
 'cut':view('Секущая плоскость ABB₁A₁',polygon=['A','B','B1','A1'])},[['A','B','C'],['A1','B1','C1']])
write(6,'Проверять параллельность плоскостей по двум пересекающимся направлениям и строить параллельные сечения.',m,[
 step('Нет общих точек','Что означает α∥β?','Две различные плоскости параллельны, если не имеют общих точек. Любая прямая одной из них также не имеет общих точек с другой и потому параллельна другой плоскости.','§ 6: определение параллельных плоскостей.','lower','definition'),
 step('Две пары прямых','Почему одной пары AB∥A₁B₁ мало?','Одно направление не определяет наклон плоскости: плоскость может поворачиваться вокруг прямой. Нужны две пересекающиеся прямые одной плоскости, соответственно параллельные двум прямым другой. Здесь AB∥A₁B₁ и AC∥A₁C₁. Для двух различных плоскостей это даёт параллельность.','Теорема 6.1.','pairs'),
 step('Почему плоскости не пересекутся','Если бы они пересеклись по c, что произошло бы с AB и AC?','Сначала A не может лежать в другой плоскости: иначе проходящие через A прямые, параллельные A₁B₁ и A₁C₁, лежали бы в ней; это AB и AC, и две плоскости совпали бы. Поэтому AB и AC не лежат в другой плоскости и по признаку 5.1 параллельны ей. При пересечении плоскостей по c свойство 5.2 даёт AB∥c и AC∥c. Через A прошли бы две разные прямые одного направления — противоречие.','Теорема 5.2 и единственность параллельной прямой.','pairs'),
 step('Параллельная плоскость через точку','Как построить её через A₁ вне ABC?','Через A₁ проведи прямые, параллельные двум пересекающимся прямым AB и AC. Они задают плоскость, параллельную ABC. Через внешнюю точку проходит ровно одна такая плоскость.','Теорема 6.2.','upper'),
 step('Сечение третьей плоскостью','Сравни прямые AB и A₁B₁ в плоскости ABB₁A₁.','Если две параллельные плоскости пересекает третья, линии пересечения параллельны. Они лежат в третьей плоскости; их пересечение дало бы общую точку исходных плоскостей, которой быть не может.','Теорема 6.3.','cut'),
 step('Равные отрезки между плоскостями','Почему AA₁=BB₁, если AA₁∥BB₁?','Параллельные прямые AA₁ и BB₁ задают плоскость. Их концы на параллельных плоскостях соединены параллельными отрезками AB и A₁B₁. Получился параллелограмм, поэтому его противоположные стороны AA₁ и BB₁ равны.','Ключевая задача 1 § 6; свойство параллелограмма.','cut')],
 'Для признака укажи обе пары параллельных прямых и отдельно покажи точку пересечения прямых первой пары направлений в одной плоскости.',
 'Два треугольных фрагмента параллельных плоскостей и одна вспомогательная секущая плоскость.')

p={'A':[-1,-1,2],'B':[2,-1,2],'C':[0,1,3],'A1':[0,-1,0],'B1':[3,-1,0],'C1':[1.5,1,0],'M':[.5,-1,2],'M1':[1.5,-1,0]}
m=model(p,[['A','B'],['B','C'],['C','A'],['A1','B1'],['B1','C1'],['C1','A1'],['A','A1'],['B','B1'],['C','C1']],
 {'rays':view('AA₁, BB₁ и CC₁ имеют одно направление',segments=[['A','A1'],['B','B1'],['C','C1']]),
 'image':view('Проекция A₁B₁C₁',polygon=['A1','B1','C1']),
 'midpoint':view('M — середина AB, M₁ — середина A₁B₁',segments=[['A','B'],['A1','B1'],['M','M1']],points=['M','M1'])},[['A','B','C'],['A1','B1','C1']])
write(7,'Различать движение, подобие и проекцию; знать, какие свойства рисунка сохраняются.',m,[
 step('Образ каждой точки','Что связывает A и A₁?','Преобразование задаёт каждой точке исходной фигуры ровно одну точку-образ. В параллельном переносе все точки смещаются на один и тот же вектор. При центральной симметрии центр O — середина каждого отрезка XX₁.','§ 7: преобразования, перенос, центральная симметрия.','rays','definition'),
 step('Движение и равные фигуры','Должны ли длины AB и A₁B₁ совпадать при любом преобразовании?','Движение сохраняет расстояние между любыми двумя точками. Перенос и центральная симметрия — движения. Две фигуры равны, если движение переводит одну в другую. Параллельная проекция, показанная здесь, вообще говоря, движением не является.','§ 7: движение и равенство фигур.','image','definition'),
 step('Подобие','Чем общий коэффициент отличается от сохранения каждой длины?','При подобии все расстояния умножаются на одно положительное число k. Движение соответствует k=1. Два куба любых размеров подобны; произвольные два параллелепипеда не обязаны быть подобными.','§ 7: преобразование подобия.','neutral','definition'),
 step('Как получить параллельную проекцию','Сравни направления AA₁, BB₁, CC₁.','Выбирают плоскость проекции и направление, не параллельное ей. Через каждую точку проводят прямую этого направления и находят её пересечение с плоскостью. Получаются A₁,B₁,C₁. Прямая вдоль направления проектирования превращается в точку.','§ 7: параллельное проектирование.','rays','definition'),
 step('Что сохраняется','Что получится из прямой, не направленной вдоль проектирования?','Её проекция — прямая, а проекция отрезка — отрезок. Параллельные прямые, не направленные вдоль проектирования, переходят в параллельные или совпадающие прямые.','Теоремы 7.1 и 7.2.','image'),
 step('Отношения и середины','Почему на проекции можно честно отметить середину?','Для отрезков одной прямой или параллельных прямых отношение длин сохраняется, если проекции не выродились в точки. В частности, AM=MB даёт A₁M₁=M₁B₁. Поэтому медианы и середины на пространственном чертеже строят по этому правилу.','Теорема 7.3.','midpoint'),
 step('Что нельзя измерять на рисунке','Сохраняется ли прямой угол при наклонной проекции?','Углы и длины вообще не сохраняются. Квадрат может изображаться обычным параллелограммом; окружность при невырожденной проекции — эллипсом, в частном случае окружностью. При проектировании вдоль её плоскости получается отрезок. Равенства и перпендикулярность подтверждают условием и теоремами.','§ 7: изображения многоугольников и окружности.','image')],
 'Прежде чем пользоваться видом рисунка, спроси: это длина или угол, либо отношение коллинеарных отрезков? В проекции эти сведения сохраняются по-разному.',
 'Треугольник и его наклонная параллельная проекция на горизонтальную плоскость; точки M и M₁ показывают сохранение середины.')

# 8. Skew AB and CD, CD parallel to AE; angle BAE is 60 degrees.
r=math.sqrt(3)
p={'A':[0,0,0],'B':[3,0,0],'C':[0,0,2],'D':[1.5,1.5*r,2],'E':[1.5,1.5*r,0]}
m=model(p,[['A','B'],['C','D'],['A','E']],
 {'skew':view('Исходные скрещивающиеся прямые AB и CD',segments=[['A','B'],['C','D']]),
 'transfer':view('Переносим направление CD: AE∥CD',segments=[['C','D'],['A','E']]),
 'angle':view('Угол между AB и CD равен меньшему углу между AB и AE',segments=[['A','B'],['A','E']],polygon=['A','B','E'])},labels=['A','B','C','D','E'])
write(8,'Сводить угол между скрещивающимися прямыми к углу между пересекающимися прямыми.',m,[
 step('Берём угол не больше 90°','Если при пересечении прямых получились 60° и 120°, какой угол между прямыми?','Углом между пересекающимися прямыми называют меньший из образованных углов, то есть угол не больше 90°. В указанном примере ответ 60°. Угол между параллельными прямыми равен 0°.','§ 8: определения.','angle','definition'),
 step('Скрещивающиеся прямые','Почему нельзя приложить транспортир к кажущемуся пересечению AB и CD на экране?','Прямые AB и CD не пересекаются в пространстве. Поэтому их направления сначала переносят в одну точку: через A проводим AE∥CD. Теперь AB и AE действительно встречаются.','§ 8: угол между скрещивающимися прямыми.','transfer','definition'),
 step('Определяем угол','Какую пару прямых теперь нужно сравнить?','Угол между AB и CD равен углу между AB и AE. На модели ∠BAE=60°, поэтому искомый угол 60°. Число задано геометрией модели, а не размером угла на экране.','Определение угла между скрещивающимися прямыми.','angle'),
 step('Выбор точки не влияет','Можно ли перенести оба направления в другую точку?','Да. Углы между двумя парами пересекающихся прямых соответственно параллельных направлений равны. Обоснование строится на параллелограммах и равенстве полученных треугольников по трём сторонам. Поэтому ответ не зависит от точки переноса.','Теорема 8.1.','transfer'),
 step('Перпендикулярность в пространстве','Обязаны ли перпендикулярные прямые пересекаться?','В принятом здесь определении прямые перпендикулярны, когда угол между ними равен 90°. Они могут быть как пересекающимися, так и скрещивающимися. Для отрезков рассматривают содержащие их прямые.','§ 8: определение перпендикулярных прямых и отрезков.','skew','definition')],
 'Проведи через удобную вершину прямую, параллельную второй исходной прямой. Потом найди меньший угол в получившемся плоском треугольнике.',
 'CD расположена над плоскостью ABE и параллельна AE. Модель иллюстрирует перенос одного направления.')

# 9. Perpendicular to a plane and reflected points.
p={'O':[0,0,0],'A':[3,0,0],'B':[0,3,0],'M':[0,0,2],'M1':[0,0,-2],'Q':[2,2,0],'N':[2,2,2]}
m=model(p,[['O','A'],['O','B'],['M','M1'],['Q','N']],
 {'two':view('MO перпендикулярна двум пересекающимся прямым OA и OB',segments=[['M','O'],['O','A'],['O','B']]),
 'normal':view('MO⊥плоскости AOB',polygon=['O','A','B'],segments=[['M','O']]),
 'parallel':view('MO и NQ — перпендикуляры к одной плоскости',segments=[['M','O'],['N','Q']]),
 'mirror':view('M и M₁ симметричны: O — середина MM₁',segments=[['M','M1']],points=['M','O','M1'])},[['O','A','B']],labels=['O','A','B','M','M1','Q','N'])
write(9,'Проверять перпендикулярность прямой плоскости по двум направлениям и узнавать зеркальную симметрию.',m,[
 step('Определение','Достаточно ли перпендикулярности только одной прямой плоскости?','Прямая перпендикулярна плоскости, если она перпендикулярна каждой прямой этой плоскости. Проверить одну прямую недостаточно: в самой плоскости тоже можно провести к ней перпендикуляр.','§ 9: определение.','normal','definition'),
 step('Практический признак','Какие две прямые на модели пересекаются в O?','OA и OB лежат в плоскости и пересекаются. Если MO⊥OA и MO⊥OB, то MO перпендикулярна всей плоскости AOB. На практике обычно берут две удобные прямые через основание перпендикуляра.','Теорема 9.1.','two'),
 step('Почему важно пересечение','Что будет, если проверить две параллельные прямые?','Они дают лишь одно направление, поэтому такой проверки мало. Прямая внутри плоскости, перпендикулярная двум её параллельным прямым, не становится перпендикулярной плоскости. Признак требует двух пересекающихся направлений.','Условие теоремы 9.1.','two'),
 step('Параллельные перпендикуляры','Если NQ∥MO, что известно о NQ?','Если одна из двух параллельных прямых перпендикулярна плоскости, другая тоже ей перпендикулярна: угол с любой прямой плоскости сохраняется при замене на параллельную. Обратно, две различные прямые, перпендикулярные одной плоскости, параллельны.','Теоремы 9.2 и 9.3.','parallel'),
 step('Единственный перпендикуляр','Сколько перпендикулярных данной плоскости прямых проходит через M?','Через любую точку пространства проходит ровно одна прямая, перпендикулярная данной плоскости. Поэтому основание перпендикуляра из M определяется однозначно.','Теорема 9.4.','normal'),
 step('Зеркальные точки','Какие два условия связывают M и M₁?','MM₁ перпендикулярен плоскости, а плоскость делит MM₁ пополам: OM=OM₁. Это определяет симметрию точек относительно плоскости. Точки самой плоскости остаются на месте.','§ 9: симметрия относительно плоскости.','mirror','definition'),
 step('Плоскость симметрии фигуры','Что нужно проверить для всей фигуры?','Для каждой её точки отражённая точка должна также принадлежать фигуре. Зеркальная симметрия сохраняет расстояния, поэтому является движением. Но наличие одной симметричной пары точек ещё не доказывает симметрию всей фигуры.','§ 9: определение симметричной фигуры; свойство зеркального отражения.','mirror')],
 'Отметь плоскость, затем найди в ней две пересекающиеся прямые. К каждой из них отдельно обоснуй прямой угол с проверяемой прямой.',
 'MO и NQ — нормали к горизонтальной плоскости; M₁ — отражение M относительно неё.')

p={'O':[0,0,0],'M':[0,0,3],'A':[4,0,0],'B':[0,2,0],'C':[-2,-1,0]}
m=model(p,[['M','O'],['M','A'],['O','A'],['M','B'],['O','B']],
 {'perp':view('MO — перпендикуляр, O — его основание',segments=[['M','O']],polygon=['A','B','C']),
 'incline':view('MA — наклонная, OA — её ортогональная проекция',segments=[['M','A'],['O','A']]),
 'triangle':view('Прямоугольный треугольник MOA',polygon=['M','O','A']),
 'compare':view('Наклонные MA и MB проведены из одной точки M',segments=[['M','A'],['M','B'],['O','A'],['O','B']])},[['A','B','C']])
write(10,'Различать перпендикуляр, наклонную, её проекцию и расстояние до плоскости.',m,[
 step('Ортогональная проекция','Куда проектируется точка M?','Ортогональное проектирование ведут по прямым, перпендикулярным плоскости. Проекция M — основание O перпендикуляра MO. Точка A плоскости проектируется в себя, поэтому проекция MA — OA.','§ 10: ортогональное проектирование.','incline','definition'),
 step('Наклонная и перпендикуляр','Где расположен прямой угол треугольника MOA?','MO⊥плоскости, значит, MO⊥OA. Отрезок MA при A≠O — наклонная, а OA — её проекция. В прямоугольном треугольнике MOA наклонная MA является гипотенузой.','Определения § 10; перпендикулярность прямой плоскости.','triangle'),
 step('Кратчайшее расстояние','Почему нельзя назвать MA расстоянием до плоскости?','По Пифагору MA²=MO²+OA². Если A≠O, то OA>0 и MA>MO. Поэтому ближайшая к M точка плоскости — O, а расстояние до плоскости равно MO. Для точки самой плоскости расстояние равно нулю.','Теорема 10.1; определение расстояния.','perp'),
 step('Сравниваем наклонные','Какая наклонная длиннее при OA>OB?','MA²=MO²+OA², MB²=MO²+OB². Общий катет MO одинаков, поэтому большая проекция даёт большую наклонную; равные проекции дают равные наклонные, и наоборот.','Теорема Пифагора в двух прямоугольных треугольниках.','compare'),
 step('Параллельные объекты','Почему расстояние до параллельной плоскости можно измерять из любой точки?','Все точки прямой, параллельной плоскости, равноудалены от неё: параллельные перпендикуляры и линия их оснований образуют прямоугольник. Так же определяют расстояние между двумя параллельными плоскостями.','Ключевые задачи 2 и 3 § 10.','perp'),
 step('Скрещивающиеся прямые','Какой отрезок измеряет расстояние между ними?','Общий перпендикуляр — отрезок с концами на двух прямых, перпендикулярный обеим. Для скрещивающихся прямых он существует, а его длина равна расстоянию между параллельными плоскостями, содержащими эти прямые.','§ 10: общий перпендикуляр и расстояние между скрещивающимися прямыми.','neutral','definition')],
 'Выпиши три отрезка: MO — высота к плоскости, MA — наклонная, OA — проекция. Затем поставь прямой угол именно в O.',
 'Из одной точки M проведены перпендикуляр MO и две наклонные MA,MB к одной плоскости.')

p={'B':[0,0,0],'A':[0,0,3],'C':[3,0,0],'D':[3,-2,0],'E':[3,2,0]}
m=model(p,[['A','B'],['A','C'],['B','C'],['D','E']],
 {'projection':view('BC — проекция наклонной AC',segments=[['A','B'],['A','C'],['B','C']]),
 'inplane':view('DE лежит в плоскости BDE и перпендикулярна BC',segments=[['D','E'],['B','C']],polygon=['B','D','E']),
 'all':view('DE перпендикулярна плоскости ABC, значит, и AC',polygon=['A','B','C'],segments=[['D','E'],['A','C']])},[['B','D','E']],labels=['A','B','C','D','E'])
write(11,'Переносить перпендикулярность с проекции наклонной на наклонную и обратно.',m,[
 step('Назовём три объекта','Где перпендикуляр, наклонная и проекция?','AB⊥плоскости BDE. AC — наклонная, BC — её проекция. Прямая DE лежит в этой плоскости и проходит через C. Именно различение AC и BC помогает применить теорему без путаницы.','Условия теоремы 11.1.','projection','given'),
 step('Прямая теорема','Если DE⊥BC, что можно сказать об AC?','Прямая в плоскости, перпендикулярная проекции наклонной, перпендикулярна и самой наклонной. Значит, DE⊥AC.','Теорема о трёх перпендикулярах.','inplane'),
 step('Почему это верно','К каким двум прямым плоскости ABC перпендикулярна DE?','Из AB⊥плоскости BDE следует AB⊥DE. По условию BC⊥DE. Прямые AB и BC пересекаются, поэтому DE⊥плоскости ABC. Тогда DE перпендикулярна любой её прямой, в частности AC.','Признак перпендикулярности прямой и плоскости; определение.','all'),
 step('Обратная теорема','Теперь известно DE⊥AC. Как получить DE⊥BC?','По-прежнему DE⊥AB, так как AB⊥плоскости BDE. Прямые AB и AC пересекаются и лежат в ABC. Поэтому DE⊥ABC, откуда DE⊥BC.','Обратная часть теоремы 11.1.','all'),
 step('«Тогда и только тогда»','Какие два утверждения равносильны?','При сохранении условий AB⊥плоскости и DE⊂плоскости получаем: DE⊥AC тогда и только тогда, когда DE⊥BC. При решении сначала обязательно докажи, что BC — именно ортогональная проекция AC.','Теорема 11.1 в форме равносильности.','projection')],
 'Сначала найди основание перпендикуляра из внешней точки. Соедини его с основанием наклонной: это и будет нужная проекция.',
 'Вертикальная плоскость ABC содержит перпендикуляр AB и наклонную AC. Прямая DE в горизонтальной плоскости проходит через C.')

p={'O':[0,0,0],'M':[0,0,3],'A':[3*r,0,0],'B':[-1,2,0],'C':[-1,-2,0]}
m=model(p,[['M','O'],['M','A'],['O','A']],
 {'height':view('MO⊥плоскости',segments=[['M','O']]),
 'projection':view('OA — ортогональная проекция MA',segments=[['M','A'],['O','A']]),
 'angle':view('Искомый угол MAO расположен при A',polygon=['M','O','A'],segments=[['A','M'],['A','O']],points=['A'])},[['A','B','C']],labels=['M','O','A'])
write(12,'Находить угол между прямой и плоскостью через ортогональную проекцию.',m,[
 step('Сначала проекция','Почему OA — проекция MA?','Точка M проектируется в O, а A уже лежит в плоскости. Поэтому наклонная MA проектируется в OA. Прямые MA и OA пересекаются в A.','Ортогональное проектирование.','projection'),
 step('Какой именно угол','При какой вершине находится угол между наклонной и плоскостью?','Для наклонной прямой это угол между ней и её ортогональной проекцией. Здесь искомый угол — острый ∠MAO при A. Угол AMO при M — другой: он между наклонной и перпендикуляром.','§ 12: определение угла между прямой и плоскостью.','angle','definition'),
 step('Два крайних случая','Какие углы отвечают горизонтальному и вертикальному направлениям?','Если прямая лежит в плоскости или параллельна ей, угол равен 0°. Если она перпендикулярна плоскости, угол равен 90°. В общем случае угол между прямой и плоскостью находится от 0° до 90° включительно.','§ 12: определение.','height','definition'),
 step('Используем прямоугольный треугольник','Какая сторона противолежит углу φ=∠MAO?','В треугольнике MOA прямой угол при O. Поэтому sin φ=MO/MA, cos φ=OA/MA, tg φ=MO/OA. На модели MO=3, OA=3√3, MA=6, так что sin φ=1/2 и φ=30°.','Тригонометрия прямоугольного треугольника; теорема Пифагора.','angle'),
 step('Равные углы из одной точки','Если две наклонные из M образуют одинаковый угол с плоскостью, что можно сравнить?','У их прямоугольных треугольников общий катет MO и равные противолежащие острые углы. Треугольники равны, поэтому проекции наклонных равны. Основание O равноудалено от оснований этих наклонных.','Ключевая задача § 12.','projection')],
 'Запиши искомый угол тремя буквами. Средняя буква должна быть точкой пересечения наклонной с плоскостью, а не внешней точкой.',
 'Наклонная MA, её проекция OA и перпендикуляр MO образуют один прямоугольный треугольник.')

# 13. Obtuse 120 degree dihedral; inter-plane angle is 60 degrees.
p={'O':[0,0,0],'L':[-2,0,0],'R':[2,0,0],'A':[0,2,0],'B':[0,-1,r]}
m=model(p,[['L','R'],['O','A'],['O','B']],
 {'edge':view('LR — общее ребро двух полуплоскостей',segments=[['L','R']]),
 'linear':view('OA⊥LR и OB⊥LR: ∠AOB — линейный угол',segments=[['O','A'],['O','B']],polygon=['O','A','B']),
 'facea':view('Грань со стороной OA',polygon=['L','R','A']),
 'faceb':view('Грань со стороной OB',polygon=['L','R','B'])},[['L','R','A'],['L','R','B']])
write(13,'Строить линейный угол и отличать выбранный двугранный угол от угла между плоскостями.',m,[
 step('Грани и ребро','Какие два фрагмента встречаются по LR?','Грани двугранного угла — две полуплоскости с общей граничной прямой, его ребром. Вместе с выбранной частью пространства они образуют двугранный угол. В основном курсе рассматривается выпуклый двугранный угол.','§ 13: двугранный угол.','edge','definition'),
 step('Проводим два перпендикуляра','Почему произвольные лучи из O не подходят?','На ребре выбирают одну точку O. В каждой грани проводят из O луч, перпендикулярный ребру: OA⊥LR и OB⊥LR. Только тогда ∠AOB является линейным углом выбранного двугранного угла.','§ 13: линейный угол.','linear','definition'),
 step('Измеряем двугранный угол','Можно ли выбрать другую точку на ребре?','Линейные углы, построенные в разных точках ребра, равны: их соответствующие стороны параллельны. Величина двугранного угла равна величине любого его линейного угла.','Теорема 8.1; определение величины двугранного угла.','linear'),
 step('Два разных вопроса','На модели выбранный линейный угол равен 120°. Каков угол между плоскостями?','Выбранный двугранный угол равен 120°. Но угол между пересекающимися плоскостями — наименьший из образованных двугранных углов, не больше 90°. Поэтому угол между этими плоскостями равен 180°−120°=60°.','§ 13: определение угла между плоскостями.','linear','definition'),
 step('Углы с многоугольниками','Что означает «угол между гранью и основанием»?','Берут угол между плоскостями, содержащими эти многоугольники. Между параллельными плоскостями угол считают равным 0°. Если спрашивают конкретный двугранный угол при ребре тела, надо сохранить выбранные полуплоскости и не заменять тупой угол острым.','§ 13: углы между многоугольниками и плоскостями.','faceb','definition')],
 'Найди ребро пересечения плоскостей. В одной точке ребра построй по перпендикуляру в каждой плоскости; затем уточни, какой угол требуется — конкретный двугранный или меньший между плоскостями.',
 'Выбранные грани образуют двугранный угол 120°, а содержащие их плоскости — угол 60°. Это намеренно разные величины.')

p={'O':[0,0,0],'A':[0,0,3],'B':[0,3,0],'L':[-2,0,0],'R':[2,0,0]}
m=model(p,[['L','R'],['O','A'],['O','B']],
 {'vertical':view('Плоскость LRA содержит перпендикуляр AO',polygon=['L','R','A'],segments=[['A','O']]),
 'horizontal':view('Горизонтальная плоскость LRB',polygon=['L','R','B']),
 'linear':view('∠AOB=90° — линейный угол',segments=[['O','A'],['O','B']],polygon=['A','O','B'])},[['L','R','A'],['L','R','B']])
write(14,'Доказывать перпендикулярность плоскостей и находить перпендикуляр к одной из них внутри другой.',m,[
 step('Определение','Каков угол между плоскостями LRA и LRB?','Плоскости перпендикулярны, если угол между ними равен 90°. Здесь лучи OA и OB перпендикулярны общему ребру LR, а ∠AOB=90°, поэтому плоскости перпендикулярны.','§ 14: определение.','linear','definition'),
 step('Признак','Какой одной прямой достаточно внутри плоскости LRA?','Если плоскость содержит прямую, перпендикулярную другой плоскости, то эти плоскости перпендикулярны. Здесь AO лежит в LRA и AO⊥LRB.','Теорема 14.1.','vertical'),
 step('Почему признак верен','Почему ∠AOB одновременно линейный и прямой?','AO перпендикулярна каждой прямой плоскости LRB, в частности LR и OB. Выбираем OB⊥LR. Тогда ∠AOB — линейный угол, и он прямой. Следовательно, угол между плоскостями 90°.','Доказательство теоремы 14.1.','linear'),
 step('Обратное свойство','Какая прямая вертикальной плоскости будет перпендикулярна горизонтальной?','Если две плоскости перпендикулярны, прямая одной плоскости, перпендикулярная линии их пересечения, перпендикулярна другой плоскости. Нельзя брать произвольную прямую вертикальной плоскости: например, сама LR лежит в обеих.','Теорема 14.2.','vertical'),
 step('Где проходит высота','Из точки A плоскости LRA опускают перпендикуляр к LRB. Покинет ли он LRA?','Нет. В LRA проведём из A перпендикуляр к LR. По предыдущему свойству он перпендикулярен LRB. Единственность перпендикуляра к плоскости означает, что это и есть искомая прямая.','Ключевая задача 1 § 14; теорема 9.4.','vertical'),
 step('Пересечение двух перпендикулярных плоскостей','Если две разные пересекающиеся плоскости обе перпендикулярны третьей, что известно об их общей прямой?','Их линия пересечения перпендикулярна третьей плоскости. Через её точку проходит единственный перпендикуляр к третьей плоскости; по предыдущему свойству он лежит в обеих исходных плоскостях, значит, совпадает с линией пересечения.','Ключевая задача 2 § 14.','vertical')],
 'Плоскости сравнивай через прямую: найди в первой прямую, перпендикулярную второй. Для обратного свойства сперва найди линию пересечения плоскостей.',
 'Две перпендикулярные плоскости имеют ребро LR; AO и BO показывают их линейный угол.')

# 15. Tilted triangle, projection and altitude; cos tilt = 1/2.
p={'A':[-2,0,0],'C':[2,0,0],'D':[0,0,0],'B':[0,1,r],'B1':[0,1,0]}
m=model(p,[['A','B'],['B','C'],['C','A'],['A','B1'],['B1','C'],['B','B1'],['B','D'],['B1','D']],
 {'original':view('Треугольник ABC до проектирования',polygon=['A','B','C']),
 'projected':view('Ортогональная проекция AB₁C',polygon=['A','B1','C']),
 'height':view('Общее основание AC; высота DB проектируется в DB₁',segments=[['B','D'],['B1','D'],['B','B1']],polygon=['B','D','B1'])},[['A','B','C'],['A','B1','C']])
write(15,'Связывать площадь фигуры и площадь её ортогональной проекции через угол между плоскостями.',m,[
 step('Сначала проверяем вид проекции','Почему BB₁ должно быть перпендикулярно плоскости AB₁C?','Формула площади относится к ортогональной проекции. При произвольном наклонном проектировании она неверна. На модели B₁ — основание перпендикуляра из B, а A,C уже лежат в плоскости проекции.','Условия теоремы 15.1.','projected','given'),
 step('Сравниваем высоты','Как связаны DB и DB₁?','AC — общее основание треугольников. DB⊥AC и DB₁⊥AC, поэтому ∠BDB₁ — угол α между плоскостями. В прямоугольном треугольнике BDB₁ имеем DB₁=DB·cos α.','Теорема о трёх перпендикулярах; косинус острого угла.','height'),
 step('Формула для треугольника','Что изменилось в произведении основания на высоту?','S(ABC)=AC·DB/2, S(AB₁C)=AC·DB₁/2. Подставляем DB₁=DB·cos α: Sпроекции=Sфигуры·cos α. Основание не изменилось, высота уменьшилась в cos α раз.','Формула площади треугольника; теорема 15.1.','projected'),
 step('Если сторона треугольника не параллельна проекции','Как свести произвольный треугольник к уже разобранному случаю?','При 0°<α<90° проведи через каждую вершину в плоскости треугольника прямую, параллельную линии пересечения двух плоскостей. Если ни одна сторона исходного треугольника не параллельна плоскости проекции, одна из трёх проведённых прямых разбивает треугольник на два. Их общая сторона параллельна плоскости проекции. Для каждого можно заменить плоскость проекции параллельной плоскостью через эту сторону: площадь проекции не изменится. Применяем доказанную формулу и складываем площади.','Промежуточный шаг доказательства теоремы 15.1.','original'),
 step('Переход к многоугольнику','Почему можно сложить площади треугольников?','Выпуклый многоугольник разбиваем диагоналями на треугольники. Для всех угол между его плоскостью и плоскостью проекции один и тот же. Проекции при α<90° не накладываются внутренностями, поэтому их площади складываются и дают Sпроекции=S·cos α.','Доказательство теоремы 15.1: разбиение на треугольники.','original'),
 step('Проверяем смысл','Может ли площадь ортогональной проекции быть больше площади фигуры?','Нет: 0≤cos α≤1. При α=0° площадь сохраняется; при 0°<α<90° уменьшается. При α=90° фигура проектируется в отрезок, его площадь равна 0. Обратную формулу S=Sпроекции/cos α используют лишь при cos α≠0.','Свойства косинуса; вырожденная ортогональная проекция.','projected'),
 step('Пример модели','Если α=60°, какая доля площади сохранится?','cos 60°=1/2. На модели AC=4, DB=2, DB₁=1. Поэтому S(ABC)=4, S(AB₁C)=2 — ровно половина.','Площадь треугольника; cos 60°=1/2.','height')],
 'Обозначь отдельно S — настоящую площадь и Sпроекции — площадь на плоскости. Угол α берётся между плоскостями, а не между случайным ребром и плоскостью.',
 'Два треугольника имеют общее основание AC. Высоты DB и DB₁ наглядно объясняют множитель cos α.')

# 16. A right triangular prism.
p={'A':[-2,-1,0],'B':[2,-1,0],'C':[0,2,0],'A1':[-2,-1,3],'B1':[2,-1,3],'C1':[0,2,3]}
e=[['A','B'],['B','C'],['C','A'],['A1','B1'],['B1','C1'],['C1','A1'],['A','A1'],['B','B1'],['C','C1']]
f=[['A','B','C'],['A1','B1','C1'],['A','B','B1','A1'],['B','C','C1','B1'],['C','A','A1','C1']]
m=model(p,e,{'base':view('Одно из двух равных оснований',polygon=['A','B','C']),
 'height':view('В прямой призме AA₁ — высота и боковое ребро',segments=[['A','A1']]),
 'side':view('Боковая грань ABB₁A₁ — прямоугольник',polygon=['A','B','B1','A1']),
 'top':view('Второе основание A₁B₁C₁',polygon=['A1','B1','C1'])},f)
write(16,'Узнавать прямую и правильную призму, отличать высоту от бокового ребра и вычислять площадь поверхности.',m,[
 step('Многогранник','Какие многоугольники образуют поверхность?','Многогранник — тело, поверхность которого состоит из конечного числа многоугольников. Соседние грани имеют общее ребро. Выпуклый многогранник находится по одну сторону от плоскости каждой своей грани. Площадь поверхности — сумма площадей граней.','§ 16: определения.','neutral','definition'),
 step('Узнаём призму','Какие две грани служат основаниями?','У n-угольной призмы два равных n-угольника в параллельных плоскостях, а боковые грани — параллелограммы. Все боковые рёбра параллельны и равны. На модели основания ABC и A₁B₁C₁.','§ 16: определение и свойства призмы.','base','definition'),
 step('Высота','Когда боковое ребро является высотой?','Высота измеряет расстояние между плоскостями оснований и перпендикулярна им. В прямой призме боковые рёбра перпендикулярны основаниям, поэтому их длина равна высоте h. В наклонной призме боковое ребро всегда длиннее высоты: оно является наклонной к плоскости основания.','§ 16: высота, прямая и наклонная призмы.','height','definition'),
 step('Правильная призма','Достаточно ли только правильного основания?','Правильная призма должна одновременно быть прямой и иметь правильный многоугольник в основании. У текущей прямой призмы основание не равностороннее, поэтому она не правильная.','§ 16: определение правильной призмы.','base','definition'),
 step('Диагональное сечение','Какие боковые рёбра определяют такое сечение?','В выпуклой призме с n>3 берут два боковых ребра, не принадлежащих одной боковой грани. Секущая плоскость пересекает основания по диагоналям. Получается параллелограмм, а в прямой призме — прямоугольник. У показанной треугольной призмы такого диагонального сечения нет.','§ 16: диагональное сечение.','neutral','definition'),
 step('Боковая поверхность прямой призмы','Сложи площади прямоугольных боковых граней.','Если стороны основания a₁,…,aₙ, а высота h, то Sбок=a₁h+…+aₙh=(a₁+…+aₙ)h=Pосн·h. Здесь использована именно прямая призма: все боковые грани прямоугольники высоты h.','Теорема 16.1.','side'),
 step('Полная поверхность','Какие две грани ещё нужно добавить?','К боковой поверхности добавляют оба равных основания: Sполн=Sбок+2Sосн. Для наклонной призмы формулу Pосн·h автоматически применять нельзя; в ключевой задаче используют периметр сечения, перпендикулярного боковым рёбрам, и длину бокового ребра.','§ 16: полная поверхность; ключевая задача.','top')],
 'Укажи, что задано: высота или боковое ребро, прямая призма или наклонная. Формула Pосн·h требует прямой призмы.',
 'Прямая треугольная призма с неравносторонним основанием позволяет отличить «прямую» от «правильной».')

p,e,f=box(4,3,2)
p['O']=[2,1.5,1]
m=model(p,e+[ ['A','C1'],['A1','C'],['A','C'] ],
 {'base':view('Основание ABCD',polygon=['A','B','C','D']),
 'diagonal':view('Диагональное сечение ACC₁A₁',polygon=['A','C','C1','A1'],segments=[['A','C1'],['A1','C']],points=['O']),
 'pythagoras':view('Прямоугольный треугольник ACC₁',polygon=['A','C','C1'],segments=[['A','C'],['C','C1'],['A','C1']])},f,labels=['A','B','C','D','A1','C1','O'])
write(17,'Различать виды параллелепипедов и находить диагональ прямоугольного параллелепипеда.',m,[
 step('Определение','Что должно быть основанием параллелепипеда?','Параллелепипед — призма с основанием-параллелограммом. Все шесть его граней — параллелограммы. Противолежащие грани лежат в параллельных плоскостях.','§ 17: определение и свойство граней.','base','definition'),
 step('Прямой, прямоугольный, куб','Какие дополнительные условия добавляются?','У прямого параллелепипеда боковые рёбра перпендикулярны основанию. Если основание ещё и прямоугольник, параллелепипед прямоугольный. Если три измерения прямоугольного параллелепипеда равны, это куб.','§ 17: виды параллелепипедов.','neutral','definition'),
 step('Общая середина диагоналей','Почему AC₁ и A₁C делятся пополам?','Четырёхугольник ACC₁A₁ — параллелограмм. Его диагонали AC₁ и A₁C пересекаются и делятся пополам в O. Рассматривая аналогичные диагональные параллелограммы, получаем ту же середину у всех четырёх диагоналей тела.','Теорема 17.1.','diagonal'),
 step('Центральная симметрия','Какие вершины меняются местами при симметрии относительно O?','Противоположные вершины, например A и C₁, симметричны относительно O. Симметрия переводит каждую грань в противоположную и сохраняет всё тело. Поэтому O — центр симметрии параллелепипеда.','Следствие из теоремы 17.1.','diagonal'),
 step('Первый прямоугольный треугольник','Как найти диагональ AC основания?','Обозначим измерения AB=a, AD=b, AA₁=c. В прямоугольном основании AC²=a²+b². Это только диагональ грани; она ещё не равна пространственной диагонали AC₁.','Теорема Пифагора в основании.','base'),
 step('Второй прямоугольный треугольник','Почему CC₁ перпендикулярна AC?','CC₁⊥плоскости основания, поэтому CC₁⊥AC. Из треугольника ACC₁: AC₁²=AC²+CC₁²=a²+b²+c². Следовательно, d=√(a²+b²+c²). Для куба со стороной a получаем d=a√3.','Теорема 17.2.','pythagoras'),
 step('Проверяем на модели','Найди d при a=4, b=3, c=2.','Диагональ основания равна √(16+9)=5. Пространственная диагональ равна √(25+4)=√29. Она длиннее диагонали основания. Для наклонного параллелепипеда формула суммы трёх квадратов без дополнительных условий неверна.','Теорема 17.2 и её условия.','pythagoras')],
 'Не смешивай диагональ грани и диагональ тела. Сначала найди диагональ основания, затем используй второй прямоугольный треугольник с высотой.',
 'Прямоугольный параллелепипед с измерениями 4,3,2; показаны две диагонали и их общая середина O.')

p={'A':[-2,-2,0],'B':[2,-2,0],'C':[2,2,0],'D':[-2,2,0],'S':[0,0,3],'O':[0,0,0],'M':[0,-2,0]}
e=[['A','B'],['B','C'],['C','D'],['D','A'],['S','A'],['S','B'],['S','C'],['S','D'],['S','O'],['S','M'],['O','M']]
f=[['A','B','C','D'],['S','A','B'],['S','B','C'],['S','C','D'],['S','D','A']]
m=model(p,e,{'base':view('Квадрат ABCD — основание',polygon=['A','B','C','D']),
 'height':view('SO — высота пирамиды',segments=[['S','O']],points=['O']),
 'apothem':view('SM — высота боковой грани и апофема',polygon=['S','A','B'],segments=[['S','M']]),
 'right':view('SOM — прямоугольный треугольник: высота, апофема, радиус вписанной окружности',polygon=['S','O','M'])},f)
write(18,'Различать высоту, боковое ребро и апофему пирамиды; вычислять площадь правильной пирамиды.',m,[
 step('Элементы пирамиды','Какая вершина общая для боковых граней?','У n-угольной пирамиды основание — n-угольник, боковые грани — n треугольников с общей вершиной S. Боковые рёбра соединяют S с вершинами основания. Высота — перпендикуляр из S к плоскости основания.','§ 18: определения.','height','definition'),
 step('Правильная пирамида','Какие два условия выполнены у модели?','Основание ABCD — правильный многоугольник, квадрат. Основание высоты O — его центр. Поэтому пирамида правильная. Одного правильного основания без условия о положении вершины недостаточно.','§ 18: определение правильной пирамиды.','base','definition'),
 step('Равные рёбра и грани','Почему SA=SB=SC=SD?','Расстояния OA,OB,OC,OD одинаковы. В прямоугольных треугольниках SOA,SOB,SOC,SOD катет SO общий и вторые катеты равны, значит, гипотенузы равны. Боковые грани равны по трём сторонам и являются равнобедренными треугольниками.','Теорема Пифагора; третий признак равенства треугольников.','apothem'),
 step('Апофема и высота — разные отрезки','Где находится SM, а где SO?','Апофема SM — высота боковой грани правильной пирамиды, проведённая из S к стороне основания. SO — высота всего тела. Так как SM — гипотенуза прямоугольного треугольника SOM, SM²=SO²+OM²; SM>SO, поскольку OM>0. Все апофемы правильной пирамиды равны.','§ 18: апофема; теорема Пифагора.','right','definition'),
 step('Боковая поверхность','Почему в формуле появляется половина?','Каждая боковая грань — треугольник с высотой l, равной апофеме. Складываем a₁l/2+…+aₙl/2 и получаем Sбок=Pосн·l/2. Для полной поверхности добавляем одно основание: Sполн=Sбок+Sосн.','Теорема 18.1; площадь треугольника.','apothem'),
 step('Диагональное сечение и тетраэдр','Что получится при сечении через S и диагональ основания?','Для выпуклой пирамиды с n>3 такое сечение — треугольник. Правильная треугольная пирамида становится правильным тетраэдром только тогда, когда все её рёбра равны: одного слова «правильная» для этого недостаточно.','§ 18: диагональное сечение и правильный тетраэдр.','neutral','definition'),
 step('Где искать основание высоты','Что даёт равенство всех боковых рёбер, даже у неправильного основания?','Из SA²=SO²+OA² и аналогичных равенств следует: равные боковые рёбра дают равные OA,OB,… . Поэтому O — центр окружности, описанной около основания, если такая пирамида существует. Равенство углов боковых рёбер с основанием даёт тот же вывод. Центр может находиться вне многоугольника.','Свойство § 18; ключевые задачи §§10,12.','height')],
 'Отдельно назови три отрезка: SO — высота тела; SA — боковое ребро; SM — апофема. В формуле боковой площади правильной пирамиды требуется SM.',
 'Правильная четырёхугольная пирамида: O — центр основания, M — середина стороны AB.')

p={'A':[-2,-2,0],'B':[2,-2,0],'C':[2,2,0],'D':[-2,2,0],
   'A1':[-1,-1,2],'B1':[1,-1,2],'C1':[1,1,2],'D1':[-1,1,2],
   'O':[0,0,0],'O1':[0,0,2],'M':[0,-2,0],'M1':[0,-1,2]}
e=[['A','B'],['B','C'],['C','D'],['D','A'],['A1','B1'],['B1','C1'],['C1','D1'],['D1','A1'],['A','A1'],['B','B1'],['C','C1'],['D','D1'],['O','O1'],['M','M1']]
f=[['A','B','C','D'],['A1','B1','C1','D1'],['A','B','B1','A1'],['B','C','C1','B1'],['C','D','D1','C1'],['D','A','A1','D1']]
m=model(p,e,{'bases':view('Два основания лежат в параллельных плоскостях',polygon=['A1','B1','C1','D1']),
 'height':view('OO₁ — высота усечённой пирамиды',segments=[['O','O1']],points=['O','O1']),
 'apothem':view('MM₁ — высота равнобокой боковой трапеции',polygon=['A','B','B1','A1'],segments=[['M','M1']])},f,labels=['A','B','A1','B1','M','M1','O','O1'])
m['views']['neutral']['points']=list(m['labelNames'])
m['labelNames']=[]
write(19,'Узнавать правильную усечённую пирамиду и выводить формулу её боковой поверхности.',m,[
 step('Откуда получается фигура','Как нужно расположить секущую плоскость?','Пирамиду пересекают плоскостью, параллельной основанию, между основанием и вершиной. Отсекается меньшая пирамида, а оставшаяся часть — усечённая пирамида. Произвольный наклонный срез не даёт усечённую пирамиду в этом определении.','§ 19: определение.','bases','definition'),
 step('Два основания и боковые грани','Почему боковые грани — трапеции?','Усечённая пирамида имеет два подобных многоугольных основания в параллельных плоскостях. Параллельные плоскости пересекают каждую боковую грань исходной пирамиды по параллельным прямым. Поэтому оставшаяся часть грани — трапеция.','§ 19; свойство параллельных плоскостей.','apothem'),
 step('Высота','Как измеряется расстояние между основаниями?','Высота перпендикулярна плоскостям оснований; её длина — расстояние между ними. На модели это OO₁. Боковое ребро AA₁ и отрезок MM₁ не являются высотой тела.','§ 19: высота усечённой пирамиды.','height','definition'),
 step('Правильная усечённая пирамида','Какое условие было у исходной пирамиды?','Она получается из правильной пирамиды параллельным сечением. Её основания — правильные многоугольники, боковые грани — равные равнобокие трапеции. Отрезок между серединами параллельных сторон боковой грани — её высота и апофема усечённой пирамиды.','§ 19: правильная усечённая пирамида и апофема.','apothem','definition'),
 step('Площадь одной боковой грани','Какие основания и высоту имеет трапеция ABB₁A₁?','Её основания — AB и A₁B₁, высота — апофема l=MM₁. Поэтому площадь грани равна (AB+A₁B₁)·l/2. У всех боковых граней правильной усечённой пирамиды одна и та же апофема.','Формула площади трапеции.','apothem'),
 step('Сумма боковых граней','Что получится после сложения длин всех нижних и верхних сторон?','Сумма нижних сторон — периметр P нижнего основания, верхних — периметр P₁ верхнего. Поэтому Sбок=(P+P₁)·l/2. Для полной поверхности добавляем площади обоих оснований: Sполн=Sбок+Sосн+Sосн₁.','Теорема 19.1.','bases')],
 'В формуле Sбок=(P+P₁)l/2 буква l означает апофему боковой трапеции, а не высоту тела и не боковое ребро.',
 'Правильная четырёхугольная усечённая пирамида. Апофема MM₁ и высота OO₁ показаны отдельно; скрытые подписи вершин убраны.')

